B.XS=new A.cO([1,"Ch\xfang t\xf4i ghi nh\u1eadn b\u1ea1n \u0111\xe3 2 ng\xe0y ch\u01b0a \u0111\u1ed3ng b\u1ed9 d\u1eef li\u1ec7u m\u1edbi. Y\xeau c\u1ea7u b\u1ea1n h\u1ee3p t\xe1c th\u1ef1c hi\u1ec7n \u0111\u1ed3ng b\u1ed9 \u0111\u1ec3 b\u1ea3o \u0111\u1ea3m t\xednh ch\xednh x\xe1c c\u1ee7a d\u1eef li\u1ec7u.",2,"\u0110\u1ed3ng b\u1ed9 ho\xe0n t\u1ea5t. Kh\xf4ng ghi nh\u1eadn thay \u0111\u1ed5i m\u1edbi trong d\u1eef li\u1ec7u l\u1ecbch h\u1ecdc ho\u1eb7c l\u1ecbch thi.",3,"H\u1ec7 th\u1ed1ng ghi nh\u1eadn thay \u0111\u1ed5i trong l\u1ecbch h\u1ecdc. Y\xeau c\u1ea7u b\u1ea1n ki\u1ec3m tra l\u1ea1i th\xf4ng tin tr\u01b0\u1edbc khi \u0111\u1ebfn l\u1edbp.",4,"H\u1ec7 th\u1ed1ng ghi nh\u1eadn thay \u0111\u1ed5i trong l\u1ecbch thi. Y\xeau c\u1ea7u b\u1ea1n ki\u1ec3m tra l\u1ea1i th\xf4ng tin \u0111\u1ec3 b\u1ea3o \u0111\u1ea3m tham gia \u0111\xfang ca thi.",5,"H\u1ec7 th\u1ed1ng ghi nh\u1eadn thay \u0111\u1ed5i \u0111\u1ed3ng th\u1eddi trong l\u1ecbch h\u1ecdc v\xe0 l\u1ecbch thi. Y\xeau c\u1ea7u b\u1ea1n ki\u1ec3m tra l\u1ea1i to\xe0n b\u1ed9 th\xf4ng tin li\xean quan.",6,"C\xf2n 7 ng\xe0y tr\u01b0\u1edbc k\u1ef3 thi. Vui l\xf2ng ki\u1ec3m tra l\u1ecbch.",7,"C\xf2n 3 ng\xe0y tr\u01b0\u1edbc k\u1ef3 thi. Vui l\xf2ng ki\u1ec3m tra l\u1ea1i l\u1ecbch.",8,"Ng\xe0y mai l\xe0 ng\xe0y thi. Vui l\xf2ng ki\u1ec3m tra l\u1ea1i l\u1ecbch.",9,"C\xf2n X ng\xe0y tr\u01b0\u1edbc k\u1ef3 thi. Vui l\xf2ng r\xe0 so\xe1t l\u1ea1i l\u1ecbch.",10,"B\u1ea1n \u0111ang trong k\u1ef3 thi. Vui l\xf2ng theo d\xf5i l\u1ecbch thi th\u01b0\u1eddng xuy\xean.",11,"C\xf2n X ng\xe0y, b\u1ea1n c\xf3 N m\xf4n thi. Vui l\xf2ng r\xe0 so\xe1t l\u1ecbch.",12,"\u0110\u1ed3ng b\u1ed9 ho\xe0n t\u1ea5t. H\u1ec7 th\u1ed1ng ghi nh\u1eadn thay \u0111\u1ed5i trong d\u1eef li\u1ec7u.",13,"\u0110\u1ed3ng b\u1ed9 ho\xe0n t\u1ea5t. Kh\xf4ng ghi nh\u1eadn thay \u0111\u1ed5i m\u1edbi.",14,"H\u1ec7 th\u1ed1ng ghi nh\u1eadn thay \u0111\u1ed5i. Vui l\xf2ng m\u1edf chi ti\u1ebft \u0111\u1ec3 ki\u1ec3m tra.",15,"Hi\u1ec7n ch\u01b0a ghi nh\u1eadn l\u1ecbch thi trong d\u1eef li\u1ec7u c\u1ee7a b\u1ea1n.",16,"H\xf4m nay kh\xf4ng ghi nh\u1eadn l\u1ecbch h\u1ecdc.",17,"\u0110\u1ed3ng b\u1ed9 kh\xf4ng ho\xe0n t\u1ea5t. Vui l\xf2ng th\u1ef1c hi\u1ec7n l\u1ea1i.",18,"Qu\xe1 tr\xecnh \u0111\u1ed3ng b\u1ed9 \u0111\xe3 v\u01b0\u1ee3t th\u1eddi gian ch\u1edd. Vui l\xf2ng th\u1eed l\u1ea1i."],t.TM)
